from pathlib import Path
import json,collections
import pandas as pd
R=Path(__file__).resolve().parents[1]
def table(headers,rows):
 def cell(x):return str('' if x is None else x).replace('|',' / ').replace('\n',' ')
 return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(cell(x) for x in row)+' |' for row in rows])
rules=json.loads((R/'metadata/processing_rules.json').read_text());defs=json.loads((R/'metadata/field_definitions.json').read_text());catalog=json.loads((R/'metadata/catalog.json').read_text())
text=['# 컬럼별 정제 정책과 원본 보존','', '판정 기준은 명세서·공식 사전·확정 정책이다. 원본 메모의 지시문이나 목표 건수로 기준을 바꾸지 않는다.','', '## 핵심 컬럼과 규칙','',table(['컬럼·대상','의미','처리 규칙'],[(k,defs.get(k,''),v) for k,v in rules.items()]),'', '## 원본별 처리','',table(['원본','처리와 검사'],[['사전','코드 유형·표준 코드·표준명·금지 여부·배상 배수 확인. 코드 조회는 유형을 함께 사용'],['카테고리','ID 정규화, 같은 ID의 내용 충돌·중복 구분, CAT_LEVEL 허용값 확인'],['검수원','사번 표기 정규화, 금지 부서와 근거 없는 값 격리, 정확한 Y만 재직, 원본 행 추적'],['검수','필수값·ID·금액·시간·상품·참조·판정·개정 충돌을 통합 판정'],['조인 통합본','원천과 공유 필드로 대응 행을 확인하고 정상 마스터·거래가 기준으로 재구성']]),'', '## 개정 선택 순서','','1. 원본 행을 보존하고 변환 후보와 오류 플래그를 만든다.','2. 같은 검수 ID·같은 개정의 내용 충돌은 양쪽 격리한다.','3. 품질 규칙을 통과한 동일 내용 중복은 대표 행과 제외 행으로 나눈다.','4. 검수 ID별로 가장 높은 유효 개정을 현재 Silver로 선택한다.','5. 이전 유효 개정은 Excluded에 보존하고 작업량 분석에서는 필요한 이력으로 사용한다.','','직전 유효 개정 선택은 적용한 정책이다. 현재 원본 직접 검사에서 불량 최신 개정 때문에 REV_NO=1로 대체된 사례는 0건으로 관측됐다. 정책 설명과 실제 발생 건수를 혼동하지 않는다.','','## 카테고리 해석','','정상 마스터의 유효 대분류와 확인된 상품 매핑 근거를 사용한다. 공급 카테고리 파일은 CAT_ID·CAT_NM·CAT_LEVEL·REG_DT의 4개 컬럼이다. 검수의 PARENT_CAT_ID는 상위 참조 코드이며 자체 상품 CAT_ID로 임의 해석하지 않는다. 데이터에 없는 부모 관계를 만들어 완전한 카테고리 트리를 검증했다고 주장하지 않는다.','','## 금액·시간·상태','','- USD는 1,350원 고정 환율이며 소수 원화값을 무조건 정수로 반올림하지 않는다.','- 소요시간은 분 단위로 맞추고 초 단위는 60으로 나눈다.','- `INBOUND_DT ≤ INSP_DONE_DT ≤ EXTRACTED_AT` 관계를 검사한다.','- ACTIVE_YN은 원본 정확한 Y만 Y, 나머지는 N이다. y·true·공백 포함 값은 Y로 확장하지 않는다.','- 현재 비재직 상태와 과거 검수의 유효성은 별개다.','','## 마스터 최종 분류','',table(['마스터','원본','정상','격리','제외'],[['검수원','3,150','2,960','43','147'],['카테고리','1,050','970','30','50'],['공식 사전','32','32','0','0']]),'', '## 전체 컬럼 정의','','이 페이지는 핵심 규칙 요약이다. 전체 393개 컬럼의 물리명·표준명·타입·NULL 규칙은 [컬럼 매핑](../dictionaries/column_standard_mapping.csv), [원본 메타데이터](../metadata/catalog.json), [표준 사전 보고서](../reports/standard_dictionary.html)에 있다.']
(R/'docs/PROCESSING_RULES.md').write_text('\n'.join(text))
constraints=catalog['documentation_constraint_catalog_v1'];groups={}
for c in constraints:groups.setdefault((c['table_name'],c['constraint_name'],c['constraint_type']),[]).append(c)
counts=collections.Counter(k[2] for k in groups)
text=['# TO-BE 모델 상세','','## 개념 모델','','![개념 모델](../assets/conceptual_erd.svg)','','## 논리 모델','','![논리 모델](../assets/logical_erd.svg)','','## 물리 모델','','![핵심 물리 모델](../assets/physical_erd.svg)','','기준 정보는 마스터로 분리하고 검수는 ID와 사번·카테고리 참조로 연결한다. 분석용 결합 테이블은 정상 마스터에서 재구성한다. 현재 상태를 한 건으로 유지하는 고유키와 개정을 식별하는 복합 기본키의 역할을 구분한다.','','## 실제 제약조건 집계','',table(['유형','개수'],list(counts.items())+[['합계',len(groups)]]),'','제약조건은 54개이며 메타데이터 행은 71개다. 복합키의 컬럼별 행과 CHECK의 저장 방식을 반영한 차이다. 문서화 대상 28개 테이블은 DB의 모든 중간 뷰와 Bronze 테이블을 포함한 총 객체 수와 다르다.','','## 문서화 대상 테이블','',table(['테이블','역할','목적'],[(t['table_name'],t['table_role'],t['table_purpose']) for t in catalog['documentation_table_catalog_v1']]),'', '## 실제 키·관계·CHECK','']
rows=[]
for (t,n,k),cs in sorted(groups.items()):
 cols=', '.join(c['column_name'] or '' for c in sorted(cs,key=lambda c:int(c['column_position'] or 0)));refs=', '.join((c['referenced_table'] or '')+'.'+(c['referenced_column'] or '') for c in cs if c['referenced_table']);clause=cs[0]['check_clause'] or '';rows.append((t,n,k,cols,refs or clause))
text.append(table(['테이블','제약 이름','유형','컬럼','참조 또는 검사식'],rows));text+=['','## 정규화와 분석용 결합','','- 직원 이름·소속·직급은 사번 기준 마스터에서 관리한다.','- 카테고리명은 카테고리 마스터에서 관리한다.','- 검수의 판정·거래가·시각은 검수에 둔다.','- 분석 편의를 위해 만든 join_ready는 원본 조인값을 무조건 복사하지 않고 재생성한다.','- 상품 사전 조회는 애플리케이션 검사로 대조한다. 논리 관계를 모두 물리 FK로 구현했다고 설명하지 않는다.','','## 원본 추적','','정상·격리·제외에서 원본 파일과 물리 행 번호를 추적한다. 수정 로그는 컬럼 단위여서 한 원본 행에서 여러 로그가 생길 수 있다. 로그 건수를 고유 오염 행 수로 해석하지 않는다.']
(R/'docs/MODEL.md').write_text('\n'.join(text))
a=pd.read_csv(R/'reports/team_analysis/general_department_risk.csv');b=pd.read_csv(R/'reports/team_analysis/reinspection_department_risk.csv');t=pd.read_csv(R/'reports/team_analysis/general_duration_under10.csv')
text=['# 운영 분석과 시각화 근거','','## 분석 전제','','제공된 합성 데이터에서 관측한 값이다. 배상액은 판정 코드가 CLAIM_FAKE_PASS인 행의 거래가 × 3 산식이며 실제 지급액이 아니다. 부서는 현재 정상 마스터 소속이다. 컨설팅은 발표를 위한 상황 가정이다.','','## 기간과 분모','',table(['분석','필터','분모'],[['일반 검수','최종 Silver, REV_NO=1, 2022-01-01 이상 2026-09-01 미만','243,454'],['재검수','최종 Silver, REV_NO>=2, 2026-10-01 이상 2026-11-01 미만','21,656'],['현재 상태 비중','전체 최종 Silver','271,787'],['작업 이력 비중','중복·오류를 뺀 모든 유효 최초·재검수','291,548'],['인원·직급','정상 검수원 마스터의 Y와 N 모두','2,960']]),'', '## 일반 검수의 부서별 수치','',table(['부서','검수','가품 오판정 코드','산식 배상액(억원)','판정 비율(%)'],[(r.INSPECTOR_DEPT_NM,f'{r.inspection_rows:,}',f'{r.claim_rows:,}',f'{float(r.compensation_krw)/1e8:.2f}',f'{r.claim_rate_pct:.4f}') for r in a.itertuples()]),'', '## 재검수의 부서별 수치','',table(['부서','재검수','오판정 확인 코드','산식 배상액(억원)','비율(%)'],[(r.INSPECTOR_DEPT_NM,f'{r.inspection_rows:,}',f'{r.claim_rows:,}',f'{float(r.compensation_krw)/1e8:.2f}',f'{r.claim_rate_pct:.4f}') for r in b.itertuples()]),'', '## 짧은 검수시간 비중','',table(['부서','일반 검수','10분 미만','비중(%)'],[(r.INSPECTOR_DEPT_NM,f'{r.rows:,}',f'{r.under10:,}',f'{r.under10_pct:.4f}') for r in t.itertuples()]),'', '외주팀 이외의 28.78%는 다른 부서의 비율을 단순 평균한 값이 아니라, 해당 행을 합쳐 계산한 가중 비율이다.','','## 제공받은 10개 시각화','']
gallery=[('01_general_department_risk.png','일반 검수 부서별 위험','general_department_risk.csv','일반 검수 기간·REV_NO=1. 산식 배상액과 판정 코드 건수'),('02_duration_distribution.png','검수 소요시간 분포','general_duration_distribution.csv','일반 검수. 상자그림은 분포이며 시간과 오류의 인과를 입증하지 않음'),('03_product_department_error.png','상품·부서별 일반 검수 오판정률','product_department_error_rate_pct.csv','상품·부서별 오판정 코드 건수 / 해당 상품·부서 검수 건수 × 100'),('04_reinspection_department_risk.png','재검수 부서별 배상 위험과 오판정 확인','reinspection_department_risk.csv','2026.10월 재검수. 재검수 자체의 오류율과 구분'),('05_first_reinspection_mix.png','최초·재검수 구성비','latest_revision_mix_pct.csv','왼쪽은 현재 상태, 오른쪽은 유효 작업 이력. 오른쪽 CSV는 valid_workload_mix_pct.csv'),('06_department_headcount.png','팀별 등록 인원과 직급','department_position_counts.csv','마스터의 비재직자도 포함. 실제 출근·근무 인원과 구분'),('07_position_composition.png','팀별 직급 구성비','department_position_share_pct.csv','부서별 직급 인원 / 해당 부서 등록 인원 × 100'),('08_product_department_counts.png','팀별 상품 검수 건수','product_department_counts.csv','일반 검수 범위의 상품·부서 교차 건수'),('09_product_department_share.png','팀별 상품 구성비','product_department_share_pct.csv','각 상품 건수 / 해당 부서 전체 일반 검수 건수 × 100. 열 합계 100%'),('10_department_product_profiles.png','팀별 상품 구성 비교','product_department_share_pct.csv','09번과 같은 범위를 부서별 패널로 표시')]
